import{_ as t,a0 as l,w as r,s as o,I as n,x as a,a1 as i,A as p,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"用一个开源工具实现多线程 Python 程序的可视化 | LCTT x X-CMD","titleTemplate":false,"description":"用一个开源工具实现多线程 Python 程序的可视化 | LCTT (202103) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用一个开源工具实现多线程 Python 程序的可视化 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用一个开源工具实现多线程 Python 程序的可视化 | LCTT (202103) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202103/20210312 Visualize multi-threaded Python programs with an open source tool","title":"用一个开源工具实现多线程 Python 程序的可视化","tag":"202103","desc":""},"relativePath":"202103/20210312 Visualize multi-threaded Python programs with an open source tool.md","filePath":"[post].md"}'),c={name:"202103/20210312 Visualize multi-threaded Python programs with an open source tool.md"};function g(h,s,u,m,k,f){const e=l("Link");return r(),o("div",null,[s[31]||(s[31]=n("h1",{id:"用一个开源工具实现多线程-python-程序的可视化",tabindex:"-1"},[a("用一个开源工具实现多线程 Python 程序的可视化 "),n("a",{class:"header-anchor",href:"#用一个开源工具实现多线程-python-程序的可视化","aria-label":"Permalink to “用一个开源工具实现多线程 Python 程序的可视化”"},"​")],-1)),s[32]||(s[32]=n("blockquote",null,[n("p",null,"VizTracer 可以跟踪并发的 Python 程序，以帮助记录、调试和剖析。")],-1)),s[33]||(s[33]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202103/30/230404xi9pox38ookk8xe2.jpg",alt:""})],-1)),s[34]||(s[34]=n("p",null,"并发是现代编程中必不可少的一部分，因为我们有多个核心，有许多需要协作的任务。然而，当并发程序不按顺序运行时，就很难理解它们。对于工程师来说，在这些程序中发现 bug 和性能问题不像在单线程、单任务程序中那么容易。",-1)),n("p",null,[s[1]||(s[1]=a("在 Python 中，你有多种并发的选择。最常见的可能是用 ",-1)),s[2]||(s[2]=n("code",null,"threading",-1)),s[3]||(s[3]=a(" 模块的多线程，用",-1)),s[4]||(s[4]=n("code",null,"subprocess",-1)),s[5]||(s[5]=a(" 和 ",-1)),s[6]||(s[6]=n("code",null,"multiprocessing",-1)),s[7]||(s[7]=a(" 模块的多进程，以及最近用 ",-1)),s[8]||(s[8]=n("code",null,"asyncio",-1)),s[9]||(s[9]=a(" 模块提供的 ",-1)),s[10]||(s[10]=n("code",null,"async",-1)),s[11]||(s[11]=a(" 语法。在 ",-1)),i(e,{href:"https://readthedocs.org/projects/viztracer/"},{default:p(()=>[...s[0]||(s[0]=[a("VizTracer",-1)])]),_:1}),s[12]||(s[12]=a(" 之前，缺乏分析使用了这些技术程序的工具。",-1))]),s[35]||(s[35]=d(`<p>VizTracer 是一个追踪和可视化 Python 程序的工具，对日志、调试和剖析很有帮助。尽管它对单线程、单任务程序很好用，但它在并发程序中的实用性是它的独特之处。</p><h3 id="尝试一个简单的任务" tabindex="-1">尝试一个简单的任务 <a class="header-anchor" href="#尝试一个简单的任务" aria-label="Permalink to “尝试一个简单的任务”">​</a></h3><p>从一个简单的练习任务开始：计算出一个数组中的整数是否是质数并返回一个布尔数组。下面是一个简单的解决方案：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def is_prime(n):</span></span>
<span class="line"><span>    for i in range(2, n):</span></span>
<span class="line"><span>        if n % i == 0:</span></span>
<span class="line"><span>            return False</span></span>
<span class="line"><span>    return True</span></span>
<span class="line"><span></span></span>
<span class="line"><span>def get_prime_arr(arr):</span></span>
<span class="line"><span>    return [is_prime(elem) for elem in arr]</span></span></code></pre></div><p>试着用 VizTracer 以单线程方式正常运行它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if __name__ == &quot;__main__&quot;:</span></span>
<span class="line"><span>    num_arr = [random.randint(100, 10000) for _ in range(6000)]</span></span>
<span class="line"><span>    get_prime_arr(num_arr)</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>viztracer my_program.py</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/viztracer_singlethreadtask.png" alt="Running code in a single thread" title="Running code in a single thread"></p><p>调用堆栈报告显示，耗时约 140ms，大部分时间花在 <code>get_prime_arr</code> 上。</p><p><img src="https://opensource.com/sites/default/files/uploads/viztracer_callstackreport.png" alt="call-stack report" title="call-stack report"></p><p>这只是在数组中的元素上一遍又一遍地执行 <code>is_prime</code> 函数。</p><p>这是你所期望的，而且它并不有趣（如果你了解 VizTracer 的话）。</p><h3 id="试试多线程程序" tabindex="-1">试试多线程程序 <a class="header-anchor" href="#试试多线程程序" aria-label="Permalink to “试试多线程程序”">​</a></h3><p>试着用多线程程序来做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if __name__ == &quot;__main__&quot;:</span></span>
<span class="line"><span>    num_arr = [random.randint(100, 10000) for i in range(2000)]</span></span>
<span class="line"><span>    thread1 = Thread(target=get_prime_arr, args=(num_arr,))</span></span>
<span class="line"><span>    thread2 = Thread(target=get_prime_arr, args=(num_arr,))</span></span>
<span class="line"><span>    thread3 = Thread(target=get_prime_arr, args=(num_arr,))</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    thread1.start()</span></span>
<span class="line"><span>    thread2.start()</span></span>
<span class="line"><span>    thread3.start()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    thread1.join()</span></span>
<span class="line"><span>    thread2.join()</span></span>
<span class="line"><span>    thread3.join()</span></span></code></pre></div><p>为了配合单线程程序的工作负载，这就为三个线程使用了一个 2000 元素的数组，模拟了三个线程共享任务的情况。</p><p><img src="https://opensource.com/sites/default/files/uploads/viztracer_multithread.png" alt="Multi-thread program" title="Multi-thread program"></p><p>如果你熟悉 Python 的全局解释器锁（GIL），就会想到，它不会再快了。由于开销太大，花了 140ms 多一点的时间。不过，你可以观察到多线程的并发性：</p><p><img src="https://opensource.com/sites/default/files/uploads/viztracer_concurrency.png" alt="Concurrency of multiple threads" title="Concurrency of multiple threads"></p><p>当一个线程在工作（执行多个 <code>is_prime</code> 函数）时，另一个线程被冻结了（一个 <code>is_prime</code> 函数）；后来，它们进行了切换。这是由于 GIL 的原因，这也是 Python 没有真正的多线程的原因。它可以实现并发，但不能实现并行。</p><h3 id="用多进程试试" tabindex="-1">用多进程试试 <a class="header-anchor" href="#用多进程试试" aria-label="Permalink to “用多进程试试”">​</a></h3><p>要想实现并行，办法就是 <code>multiprocessing</code> 库。下面是另一个使用 <code>multiprocessing</code> 的版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if __name__ == &quot;__main__&quot;:</span></span>
<span class="line"><span>    num_arr = [random.randint(100, 10000) for _ in range(2000)]</span></span>
<span class="line"><span>   </span></span>
<span class="line"><span>    p1 = Process(target=get_prime_arr, args=(num_arr,))</span></span>
<span class="line"><span>    p2 = Process(target=get_prime_arr, args=(num_arr,))</span></span>
<span class="line"><span>    p3 = Process(target=get_prime_arr, args=(num_arr,))</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    p1.start()</span></span>
<span class="line"><span>    p2.start()</span></span>
<span class="line"><span>    p3.start()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    p1.join()</span></span>
<span class="line"><span>    p2.join()</span></span>
<span class="line"><span>    p3.join()</span></span></code></pre></div><p>要使用 VizTracer 运行它，你需要一个额外的参数：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>viztracer --log_multiprocess my_program.py</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/viztracer_multithreadrun.png" alt="Running with extra argument" title="Running with extra argument"></p><p>整个程序在 50ms 多一点的时间内完成，实际任务在 50ms 之前完成。程序的速度大概提高了三倍。</p><p>为了和多线程版本进行比较，这里是多进程版本：</p><p><img src="https://opensource.com/sites/default/files/uploads/viztracer_comparewithmultiprocess.png" alt="Multi-process version" title="Multi-process version"></p><p>在没有 GIL 的情况下，多个进程可以实现并行，也就是多个 <code>is_prime</code> 函数可以并行执行。</p><p>不过，Python 的多线程也不是一无是处。例如，对于计算密集型和 I/O 密集型程序，你可以用睡眠来伪造一个 I/O 绑定的任务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def io_task():</span></span>
<span class="line"><span>    time.sleep(0.01)</span></span></code></pre></div><p>在单线程、单任务程序中试试：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if __name__ == &quot;__main__&quot;:</span></span>
<span class="line"><span>    for _ in range(3):</span></span>
<span class="line"><span>        io_task()</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/io-bound_singlethread.png" alt="I/O-bound single-thread, single-task program" title="I/O-bound single-thread, single-task program"></p><p>整个程序用了 30ms 左右，没什么特别的。</p><p>现在使用多线程：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if __name__ == &quot;__main__&quot;:</span></span>
<span class="line"><span>    thread1 = Thread(target=io_task)</span></span>
<span class="line"><span>    thread2 = Thread(target=io_task)</span></span>
<span class="line"><span>    thread3 = Thread(target=io_task)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    thread1.start()</span></span>
<span class="line"><span>    thread2.start()</span></span>
<span class="line"><span>    thread3.start()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    thread1.join()</span></span>
<span class="line"><span>    thread2.join()</span></span>
<span class="line"><span>    thread3.join()</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/io-bound_multithread.png" alt="I/O-bound multi-thread program" title="I/O-bound multi-thread program"></p><p>程序耗时 10ms，很明显三个线程是并发工作的，这提高了整体性能。</p><h3 id="用-asyncio-试试" tabindex="-1">用 asyncio 试试 <a class="header-anchor" href="#用-asyncio-试试" aria-label="Permalink to “用 asyncio 试试”">​</a></h3><p>Python 正在尝试引入另一个有趣的功能，叫做异步编程。你可以制作一个异步版的任务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import asyncio</span></span>
<span class="line"><span></span></span>
<span class="line"><span>async def io_task():</span></span>
<span class="line"><span>    await asyncio.sleep(0.01)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>async def main():</span></span>
<span class="line"><span>    t1 = asyncio.create_task(io_task())</span></span>
<span class="line"><span>    t2 = asyncio.create_task(io_task())</span></span>
<span class="line"><span>    t3 = asyncio.create_task(io_task())</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    await t1</span></span>
<span class="line"><span>    await t2</span></span>
<span class="line"><span>    await t3</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if __name__ == &quot;__main__&quot;:</span></span>
<span class="line"><span>    asyncio.run(main())</span></span></code></pre></div><p>由于 <code>asyncio</code> 从字面上看是一个带有任务的单线程调度器，你可以直接在它上使用 VizTracer：</p><p><img src="https://opensource.com/sites/default/files/uploads/viztracer_asyncio.png" alt="VizTracer with asyncio" title="VizTracer with asyncio"></p><p>依然花了 10ms，但显示的大部分函数都是底层结构，这可能不是用户感兴趣的。为了解决这个问题，可以使用 <code>--log_async</code> 来分离真正的任务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>viztracer --log_async my_program.py</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/log_async.png" alt="Using --log_async to separate tasks" title="Using --log_async to separate tasks"></p><p>现在，用户任务更加清晰了。在大部分时间里，没有任务在运行（因为它唯一做的事情就是睡觉）。有趣的部分是这里：</p><p><img src="https://opensource.com/sites/default/files/uploads/taskcreation.png" alt="Graph of task creation and execution" title="Graph of task creation and execution"></p><p>这显示了任务的创建和执行时间。Task-1 是 <code>main()</code> 协程，创建了其他任务。Task-2、Task-3、Task-4 执行 <code>io_task</code> 和 <code>sleep</code> 然后等待唤醒。如图所示，因为是单线程程序，所以任务之间没有重叠，VizTracer 这样可视化是为了让它更容易理解。</p><p>为了让它更有趣，可以在任务中添加一个 <code>time.sleep</code> 的调用来阻止异步循环：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>async def io_task():</span></span>
<span class="line"><span>    time.sleep(0.01)</span></span>
<span class="line"><span>    await asyncio.sleep(0.01)</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/time.sleep_call.png" alt="time.sleep call" title="time.sleep call"></p><p>程序耗时更长（40ms），任务填补了异步调度器中的空白。</p><p>这个功能对于诊断异步程序的行为和性能问题非常有帮助。</p><h3 id="看看-viztracer-发生了什么" tabindex="-1">看看 VizTracer 发生了什么？ <a class="header-anchor" href="#看看-viztracer-发生了什么" aria-label="Permalink to “看看 VizTracer 发生了什么？”">​</a></h3><p>通过 VizTracer，你可以在时间轴上查看程序的进展情况，而不是从复杂的日志中想象。这有助于你更好地理解你的并发程序。</p>`,58)),n("p",null,[s[14]||(s[14]=a("VizTracer 是开源的，在 Apache 2.0 许可证下发布，支持所有常见的操作系统（Linux、macOS 和 Windows）。你可以在 ",-1)),i(e,{href:"https://github.com/gaogaotiantian/viztracer"},{default:p(()=>[...s[13]||(s[13]=[a("VizTracer 的 GitHub 仓库",-1)])]),_:1}),s[15]||(s[15]=a("中了解更多关于它的功能和访问它的源代码。",-1))]),s[36]||(s[36]=n("hr",null,null,-1)),n("p",null,[s[17]||(s[17]=a("via: ",-1)),i(e,{href:"https://opensource.com/article/21/3/python-viztracer"},{default:p(()=>[...s[16]||(s[16]=[a("https://opensource.com/article/21/3/python-viztracer",-1)])]),_:1})]),n("p",null,[s[22]||(s[22]=a("作者：",-1)),i(e,{href:"https://opensource.com/users/gaogaotiantian"},{default:p(()=>[...s[18]||(s[18]=[a("Tian Gao",-1)])]),_:1}),s[23]||(s[23]=a(" 选题：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[19]||(s[19]=[a("lujun9972",-1)])]),_:1}),s[24]||(s[24]=a(" 译者：",-1)),i(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[20]||(s[20]=[a("wxy",-1)])]),_:1}),s[25]||(s[25]=a(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[21]||(s[21]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[28]||(s[28]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[26]||(s[26]=[a("LCTT",-1)])]),_:1}),s[29]||(s[29]=a(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:p(()=>[...s[27]||(s[27]=[a("Linux中国",-1)])]),_:1}),s[30]||(s[30]=a(" 荣誉推出",-1))])])}const T=t(c,[["render",g]]);export{_ as __pageData,T as default};
